from pathlib import Path
import json,base64
import os
ROOT=Path(__file__).resolve().parents[3];OUT=Path(os.environ.get('SPOTLIGHT_CONCEPTS_OUT',str(ROOT/'build/creative-review')));RAW=Path(__file__).resolve().parent/'originals'
D=json.loads((OUT/'conceptos.json').read_text());D['images']={p.name:'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode() for p in RAW.glob('*.png')}
D['references']=[r for r in json.loads(Path(__file__).with_name('references.json').read_text()) if r['status']==200]
html=r'''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Spotlight · Otras formas de buscar</title><style>
:root{color-scheme:dark;--bg:#0f151c;--card:#19222c;--border:#394858;--ink:#f0f4fa;--muted:#afbecf;--accent:#b5d7ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.5 system-ui,sans-serif}header,main,footer{max-width:1500px;margin:auto;padding:22px 28px}h1{font-size:clamp(29px,4vw,48px);line-height:1.1;letter-spacing:-.03em;margin:8px 0 12px}h2{font-size:27px;margin:8px 0}h3{font-size:21px;margin:8px 0}p{margin:7px 0}.muted{color:var(--muted)}.eyebrow{font:700 12px/1.4 system-ui;letter-spacing:.12em;color:var(--accent)}button,select{min-height:44px;background:#263545;color:var(--ink);border:1px solid #5b7088;border-radius:9px;padding:9px 13px;font:inherit;cursor:pointer}button:hover{border-color:#d0e4ff}button:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #f8c983;outline-offset:3px}button[aria-pressed=true],.chosen{background:var(--accent);color:#142030}.toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:12px 0}.gallery{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.card{border:1px solid var(--border);border-radius:13px;background:var(--card);overflow:hidden;min-width:0}.card-head{padding:11px 14px}.card-head h3{font-size:18px;margin:0}.card-head p{font-size:12px}.image-button{padding:0;border:0;border-radius:0;display:block;width:100%;background:#101820;cursor:zoom-in}.image-button img{width:100%;height:270px;object-fit:contain;display:block}.card-bottom{padding:10px 14px;display:flex;gap:8px;flex-wrap:wrap}.card-bottom button{font-size:13px;min-height:38px}.names-hidden .card-head{visibility:hidden}.section{margin-top:36px;border-top:1px solid var(--border);padding-top:25px}.note{border-left:3px solid #94b8e2;background:#1d2a38;padding:12px 16px;border-radius:5px;margin:14px 0}.detail-grid{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1fr);gap:20px}.shot{background:#111a24;border:1px solid var(--border);border-radius:9px;padding:10px;min-width:0}.shot img{width:100%;max-height:670px;object-fit:contain;display:block;cursor:zoom-in}.shot p{font-size:12px;color:var(--muted)}.specs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;margin:18px 0}.spec{background:#18232e;padding:18px;border-radius:10px}.spec b{display:block;font-size:13px;color:var(--accent);margin:9px 0 3px}.procon{display:grid;grid-template-columns:1fr 1fr;gap:20px}.procon>div{padding:20px;background:#1a2632;border-radius:12px}li{margin:7px 0}a{color:#b5d7ff}.summary{display:grid;grid-template-columns:1fr 1fr;gap:16px}.summary>article{padding:22px;border:1px solid var(--border);border-radius:14px;background:#1b2937}.badge{display:inline-block;border:1px solid #5b7188;border-radius:7px;padding:3px 8px;font-size:12px;color:var(--accent)}dialog{background:#111923;color:var(--ink);border:1px solid #5b7188;border-radius:13px;width:min(1480px,97vw);max-height:95vh;padding:20px}dialog::backdrop{background:#000d}.modal-head{display:flex;justify-content:space-between;gap:20px;align-items:center;position:sticky;top:-20px;background:#111923;padding:12px 0;z-index:1}.two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.two img,.one img{display:block;width:100%;height:auto}.one{max-width:1200px;margin:auto}.small{font-size:13px}.sticky{position:sticky;top:0;background:#0f151cf7;z-index:4;border-bottom:1px solid var(--border);padding:12px 28px}.sticky>.toolbar{max-width:1444px;margin:auto}textarea{display:block;width:100%;min-height:90px;border:1px solid #5b7188;background:#131d28;color:var(--ink);border-radius:9px;padding:15px;font:inherit}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:14px;border-bottom:1px solid var(--border);vertical-align:top}.scroll{overflow-x:auto}.label{color:var(--muted);font-size:12px}footer{padding-bottom:40px}.all-grid{margin-top:14px}.top-note{font-size:13px;max-width:1080px}.strong{font-weight:700}
@media(max-width:1000px){.image-button img{height:210px}.detail-grid{grid-template-columns:1fr 1fr}.specs{grid-template-columns:1fr 1fr}}
@media(max-width:700px){header,main,footer{padding:18px 14px}.sticky{padding:10px 14px}.gallery{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.image-button img{height:135px}.card-head{padding:9px}.card-head h3{font-size:15px}.card-head p{display:none}.card-bottom{padding:8px}.card-bottom button{font-size:12px;min-height:36px;padding:6px 9px}.detail-grid,.specs,.procon,.summary{grid-template-columns:1fr}.two{gap:8px}.toolbar button,.toolbar select{font-size:13px}.top-note{font-size:12px}h2{font-size:24px}}
</style><header><div class="eyebrow">SPOTLIGHT NEXT · EXPLORACIÓN CREATIVA</div><h1>Seis formas de imaginar Spotlight.</h1><p>La misma búsqueda y los mismos cuatro resultados. Cambia la interfaz completa.</p><p class="top-note muted">Laboratorio Compose/API33 · datos ficticios · paleta neutral común para comparar composición · sin modificar la app. Las capturas no son imágenes de IA ni una APK instalada.</p></header>
<nav class="sticky"><div class="toolbar"><label>Comparación <select id="device"><option value="tablet">Tablet · 1200 × 800 dp</option><option value="phone">Teléfono · 412 × 860 dp</option></select></label><label>Estado <select id="state"></select></label><button id="labels">Ocultar rótulos</button><button id="openComparison">Comparar dos</button></div></nav>
<main><section id="all"><div id="grid" class="gallery"></div><p class="label">Cada captura conserva su lienzo completo y escala común. En Cinta móvil los cuatro resultados siguen en el carril, aunque sólo se ve uno completo y el siguiente parcialmente.</p></section>
<section id="detail" class="section"><div id="conceptNav" class="toolbar"></div><h2 id="detailTitle"></h2><p id="detailTag" class="muted"></p><div id="states" class="toolbar"></div><div id="detailImages" class="detail-grid"></div><div id="specs" class="specs"></div><div id="procon" class="procon"></div><div id="interaction" class="note"></div></section>
<section class="section"><h2>Qué descarté por parecerse demasiado</h2><div class="scroll"><table><thead><tr><th>Ruta descartada</th><th>Por qué</th><th>Decisión creativa</th></tr></thead><tbody>
<tr><td>Las familias de color del catálogo anterior</td><td>Compartían demasiada silueta, estructura y recorrido. Bordes, tipografías o tonos no justifican otra propuesta.</td><td>Se preservan como historial; dejan de ser el abanico estético recomendado. Las 36 fichas funcionales siguen intactas.</td></tr>
<tr><td>Spotlight literal + Alfred literal + otra lista clásica</td><td>Tres cajas con búsqueda arriba y filas debajo seguían pareciendo la misma aplicación.</td><td>Conservé una sola lista: Consola. Reemplacé las otras por un protagonista y una cinta horizontal.</td></tr>
<tr><td>Cápsula arriba + cuatro tarjetas debajo</td><td>Era otra expansión de la misma ventana, demasiado cerca de Faro y de una consola con tarjetas.</td><td>La sustituí por Órbita: módulos separados, búsqueda central y acciones espaciales.</td></tr>
<tr><td>Mesa móvil con una lista grande</td><td>Se parecía a Consola estirada y desperdiciaba espacio.</td><td>La revisión usa un raíl de resultados a la izquierda y una mesa de destino/acciones a la derecha.</td></tr>
</tbody></table></div><p class="small muted">Descarte cualitativo por composición y revisión de capturas; no es una métrica automática de similitud. Los originales descartados y sus motivos quedan en el checkpoint.</p></section>
<section class="section"><h2>Mi recomendación para tus dispositivos</h2><div class="summary"><article><span class="badge">GALAXY TAB A9+</span><h3>Mesa</h3><p>Es la apuesta más útil si querés trabajar con resultados, documentos y acciones sin tapar unos con otros. Usa el ancho para tres zonas con responsabilidades claras.</p><p class="muted">Para abrir apps rápidamente con una ventana menor, elegiría Consola como alternativa.</p></article><article><span class="badge">MOTOROLA G86 5G</span><h3>Pulso</h3><p>Es mi candidata táctil: búsqueda abajo, resultados encima y crecimiento hacia arriba. La interfaz nace del teléfono, no de reducir un escritorio.</p><p class="muted">Su aprobación requiere probar IME, gestos e insets reales. La posición del asa representa una intención; no se probó arrastre físico.</p></article></div><p class="note">Estas recomendaciones son de diseño. No son mediciones físicas de velocidad, consumo o ergonomía. Órbita es la exploración más experimental; no la adoptaría sin evaluar navegación espacial y accesibilidad.</p></section>
<section class="section"><h2>Tu elección, sin aplicar nada todavía</h2><p>Podés elegir una propuesta o combinar decisiones. Marcar una opción no modifica Spotlight ni autoriza acciones sensibles.</p><textarea id="selection" readonly></textarea><div class="toolbar"><button id="copy">Copiar resumen</button><button id="download">Guardar selección JSON</button><button id="reset">Limpiar selección</button></div><p id="copyStatus" class="small" role="status"></p></section>
<section class="section"><h2>Límites del laboratorio</h2><p>Inicio: consulta vacía. Búsqueda/selección/acciones: «proyecto», mismos IDs y orden. Contexto: segundo resultado, «Proyecto Atlas.pdf», con texto fijo de demostración. No se extrajeron documentos ni se ejecutaron C5, Intents o acciones externas.</p><p class="muted">Los cambios de tamaño y posición se muestran como estados Compose reales. La descripción de transiciones es una intención de diseño, no una animación o prueba de WindowManager. No se simula Gboard ni se afirman pruebas físicas, rendimiento, TalkBack o actualización de APK.</p><details><summary>Referencias consultadas</summary><div id="references"></div><p class="small">Referencias para principios de composición y contexto; no se copió código ni material gráfico. Linear no pudo consultarse y no se usa como evidencia.</p></details></section>
</main><footer class="muted">Focus Studio, Preview69, C2, C5 y el catálogo de 36 funciones permanecen intactos. Esta entrega contiene exclusivamente prototipos visuales y documentación.</footer>
<dialog id="modal"><div class="modal-head"><h2 id="modalTitle"></h2><button id="close">Cerrar</button></div><div id="modalBody"></div></dialog>
<dialog id="compareDialog"><div class="modal-head"><h2>Dos propuestas, mismas condiciones</h2><button id="closeCompare">Cerrar</button></div><div class="toolbar"><label>Izquierda <select id="left"></select></label><label>Derecha <select id="right"></select></label></div><div id="compared" class="two"></div><p class="small muted">Usa el dispositivo y estado seleccionados arriba. Ampliá una imagen para leer sus controles.</p></dialog>
<script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.querySelector('#data').textContent),$=s=>document.querySelector(s);let current='P01',detailState='resultados',favorites=[];try{favorites=JSON.parse(localStorage.getItem('spotlight-imaginar-v2'))||[]}catch(e){}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const find=id=>D.concepts.find(c=>c.id===id);function src(id,device,state){return D.images[device+'-'+id+'-'+state+'.png']}
function show(title,content){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=content;$('#modal').showModal()}
function zoom(id,device,state){let c=find(id);show(c.id+' · '+c.name+' · '+device,'<div class="one"><img src="'+src(id,device,state)+'" alt="Captura completa de prototipo Compose"><p>'+esc(D.states.find(s=>s.id===state).name)+' · fuente de laboratorio, no app instalada.</p></div>')}
function favorite(id){favorites=favorites.includes(id)?favorites.filter(x=>x!==id):[...favorites,id];save();renderGrid()}
function save(){try{localStorage.setItem('spotlight-imaginar-v2',JSON.stringify(favorites))}catch(e){}$('#selection').value='Propuestas: '+(favorites.map(id=>id+' · '+find(id).name).join(', ')||'todavía sin elegir')+'\nTambién puedo combinar composición, acciones y adaptación por dispositivo.'}
function renderGrid(){const device=$('#device').value,state=$('#state').value;$('#grid').innerHTML=D.concepts.map(c=>`<article class="card"><div class="card-head"><h3>${c.id} · ${c.name}</h3><p class="muted">${c.tag}</p></div><button class="image-button" data-detail="${c.id}" aria-label="Explorar ${c.name}"><img loading="eager" src="${src(c.id,device,state)}" alt="Captura Compose ${c.name} ${state} ${device}"></button><div class="card-bottom"><button data-more="${c.id}">Explorar estados</button><button data-fav="${c.id}" class="${favorites.includes(c.id)?'chosen':''}" aria-pressed="${favorites.includes(c.id)}">${favorites.includes(c.id)?'Marcada':'Me interesa'}</button></div></article>`).join('');document.querySelectorAll('[data-detail],[data-more]').forEach(b=>b.onclick=()=>{current=b.dataset.detail||b.dataset.more;detailState=$('#state').value;renderDetail();$('#detail').scrollIntoView({behavior:'smooth'})});document.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>favorite(b.dataset.fav))}
function renderDetail(){let c=find(current);$('#detailTitle').textContent=c.id+' · '+c.name;$('#detailTag').textContent=c.tag;$('#conceptNav').innerHTML=D.concepts.map(c=>`<button data-concept="${c.id}" aria-pressed="${current===c.id}">${c.id} ${c.name}</button>`).join('');$('#states').innerHTML=D.states.map(s=>`<button data-stage="${s.id}" aria-pressed="${detailState===s.id}">${s.name}</button>`).join('');$('#detailImages').innerHTML=['tablet','phone'].map(device=>`<div class="shot"><p>${device==='tablet'?'Tablet · 1200 × 800 dp':'Teléfono · 412 × 860 dp'} · ${D.states.find(s=>s.id===detailState).name}</p><img data-zoom="${device}" src="${src(current,device,detailState)}" alt="${c.name} ${device} ${detailState}"><p>${esc(c[device])}</p></div>`).join('');$('#specs').innerHTML=[['Ventana',c.form],['Búsqueda',c.search],['Resultados',c.results],['Selección',c.selection],['Acciones',c.actions],['Contexto',c.context]].map(([k,v])=>`<div class="spec"><b>${k}</b><p>${esc(v)}</p></div>`).join('');$('#procon').innerHTML='<div><h3>Ventajas</h3><ul>'+c.pros.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div><div><h3>Costes e inconvenientes</h3><ul>'+c.cons.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div>';$('#interaction').innerHTML='<b>Recorrido propuesto:</b> '+esc(c.motion)+'<br><span class="small">'+esc(c.risk)+'</span>';document.querySelectorAll('[data-concept]').forEach(b=>b.onclick=()=>{current=b.dataset.concept;renderDetail()});document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{detailState=b.dataset.stage;renderDetail()});document.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>zoom(current,b.dataset.zoom,detailState))}
function renderCompare(){let device=$('#device').value,state=$('#state').value;$('#compared').innerHTML=[$('#left').value,$('#right').value].map(id=>{let c=find(id);return `<div><h3>${c.id} · ${c.name}</h3><img data-czoom="${id}" src="${src(id,device,state)}" alt="${c.name} ${device} ${state}" style="cursor:zoom-in"><p class="small">${esc(c.form)}</p></div>`}).join('');document.querySelectorAll('[data-czoom]').forEach(b=>b.onclick=()=>{$('#compareDialog').close();zoom(b.dataset.czoom,device,state)})}
D.states.forEach(s=>$('#state').add(new Option(s.name,s.id)));$('#state').value='resultados';D.concepts.forEach(c=>{$('#left').add(new Option(c.id+' '+c.name,c.id));$('#right').add(new Option(c.id+' '+c.name,c.id))});$('#left').value='P01';$('#right').value='P04';$('#left').onchange=renderCompare;$('#right').onchange=renderCompare;$('#device').onchange=()=>{renderGrid();renderCompare()};$('#state').onchange=()=>{renderGrid();renderCompare()};$('#openComparison').onclick=()=>{renderCompare();$('#compareDialog').showModal()};$('#closeCompare').onclick=()=>$('#compareDialog').close();$('#close').onclick=()=>$('#modal').close();$('#labels').onclick=()=>{let hidden=$('#grid').classList.toggle('names-hidden');$('#labels').textContent=hidden?'Mostrar rótulos':'Ocultar rótulos'};$('#copy').onclick=()=>{$('#selection').select();document.execCommand('copy');$('#copyStatus').textContent='Resumen seleccionado. Podés pegarlo en el chat.'};$('#download').onclick=()=>{let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({concepts:favorites},null,2)],{type:'application/json'}));a.download='Mi-Spotlight-visual.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};$('#reset').onclick=()=>{favorites=[];save();renderGrid()};$('#references').innerHTML=D.references.map(r=>'<p><a href="'+r.url+'" target="_blank" rel="noopener">'+esc(r.title)+'</a></p>').join('');save();renderGrid();renderDetail();
</script></html>'''
(OUT/'Galeria-Spotlight.html').write_text(html.replace('__DATA__',json.dumps(D,ensure_ascii=False)))
print('Offline gallery bytes:',(OUT/'Galeria-Spotlight.html').stat().st_size)
